<?php require '../includes/core.php';$u=require_user(true);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf();$allowed=['site_name'=>80,'hero_title'=>130,'hero_text'=>300,'announcement'=>240];$vals=[];foreach($allowed as $k=>$limit){$vals[$k]=mb_substr(trim((string)($_POST[$k]??'')),0,$limit);}if(trim($vals['site_name'])===''||trim($vals['hero_title'])==='')$error='Nome e título são obrigatórios.';$accent=(string)($_POST['accent']??'');if(!preg_match('/^#[0-9a-fA-F]{6}$/',$accent))$error='Escolha uma cor válida.';if(!$error){$vals['accent']=$accent;$q=db()->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($vals as $key=>$value)$q->execute([$key,$value]);notify('Personalização salva.');go('admin/settings.php');}}$v=settings();layout_start('Aparência do site',$u);?><span class="kicker">ADMIN • PERSONALIZAÇÃO</span><h1 class="page-title">Identidade visual</h1><p class="muted">Edite os textos públicos, o nome e a cor de destaque. Cada visitante pode escolher seu tema claro ou escuro.</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><div class="card admin-form"><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><?php foreach(['site_name'=>'Nome do site','hero_title'=>'Título principal da home','hero_text'=>'Descrição da home','announcement'=>'Aviso global (opcional)'] as $key=>$label):?><label class="field"><span><?=h($label)?></span><?php if($key==='hero_text'):?><textarea name="<?=$key?>" rows="3"><?=h($v[$key]??'')?></textarea><?php else:?><input name="<?=$key?>" value="<?=h($v[$key]??'')?>"><?php endif;?></label><?php endforeach;?><label class="field"><span>Cor de destaque</span><input type="color" name="accent" value="<?=h($v['accent'])?>" style="height:54px;width:160px;padding:6px"></label><button class="btn">Salvar aparência</button></form></div><?php layout_end();?>